def QB(slug,name,place,phone,logo,photo,alt,h1,rating,count,addr,owner,area,extra_lead='',extra_about='',fontset=F_OSW,acc='#c8a24a',acc2='#d9b862',hook_usp=('Centrum',None),title=None,over='Over ons'):
    lead=f'Fades, knippen en baarden in {place}. Klanten geven een {rating} uit {count} reviews.'+(' '+extra_lead if extra_lead else '')
    about=f'<p>{name} in {place} staat voor strak werk, een goede sfeer en een coupe die precies goed zit.</p><p>{count} klanten gaven gemiddeld een {rating}.</p>'+extra_about
    u2=hook_usp if hook_usp[1] else ('Lokaal',place)
    return BARB(name,place,phone,logo,photo,alt,h1,lead,f'<span><b>{rating}</b> uit {count} reviews</span><span><b>{addr[0].split(" ")[0]}</b> {place}</span><span><b>Inloop</b> &amp; afspraak</span>',
      about,[(rating,'op Google'),(str(count),'reviews'),u2,('Snel','geholpen')],addr,owner,area,acc=acc,acc2=acc2,fontset=fontset,title=title or f'{name} | {place}',over=over)

